import type { AppBundle } from './contracts';
/** The wrapper is generated by the host and never supplied by the candidate. */
export function managedModule(bundle: AppBundle) {
  const entry = `./${bundle.manifest.entrypoint.split('/').at(-1)}`;
  return `import { DurableObject } from 'cloudflare:workers';
import { ${bundle.manifest.export_name} as App } from ${JSON.stringify(entry)};
const profile = ${JSON.stringify(bundle.manifest)};
export class ManagedApp extends DurableObject {
  constructor(ctx, env) {
    super(ctx, env);
    ctx.storage.transactionSync(() => {
      ctx.storage.sql.exec('CREATE TABLE IF NOT EXISTS _yoneda_migrations (version INTEGER PRIMARY KEY, sql TEXT NOT NULL)');
      const applied = ctx.storage.sql.exec('SELECT version,sql FROM _yoneda_migrations ORDER BY version').toArray();
      if (applied.length > profile.migrations.length) throw new Error('Application migration rollback');
      for (let i=0;i<applied.length;i++) {
        if (applied[i].version !== profile.migrations[i].version || applied[i].sql !== JSON.stringify(profile.migrations[i].sql)) throw new Error('Application migration history mismatch');
      }
      for (const step of profile.migrations.slice(applied.length)) {
        for (const sql of step.sql) ctx.storage.sql.exec(sql);
        ctx.storage.sql.exec('INSERT INTO _yoneda_migrations VALUES (?,?)', step.version, JSON.stringify(step.sql));
      }
      if (!applied.length) for (const sql of profile.seed) ctx.storage.sql.exec(sql);
    });
    this.app = new App(ctx, {});
  }
  ready() {}
  fetch(request) { return this.app.fetch(request); }
}`;
}
